package com.codepilot1c.core.tools.bsl;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;import com.codepilot1c.core.edt.lang.*;
public class BslMethodBatchJobsTest {
 private Map<String,Object> args(){return Map.of("projectName","Owned","items",List.of(Map.of("filePath","Module.bsl","name","Run")));}
 @Test public void pendingContinuesOriginalRead()throws Exception {var registry=BackgroundJobRegistry.createForTest();CountDownLatch release=new CountDownLatch(1);AtomicInteger calls=new AtomicInteger();try{var first=new BslMethodBatchJobs(registry).read(args(),r->{calls.incrementAndGet();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return new BslMethodBodyResult("Owned","Module.bsl","Run","procedure",1,3,"test");},0);assertFalse(first.get("terminal").getAsBoolean());assertTrue(first.has("next_call"));String id=first.get("job_id").getAsString();release.countDown();assertEquals("DONE",registry.awaitStatus(id,2000).orElseThrow().getState().name());assertEquals(1,calls.get());}finally{release.countDown();registry.shutdown();}}
 @Test public void badRequestCreatesNoJob()throws Exception {var registry=BackgroundJobRegistry.createForTest();try{assertThrows(IllegalArgumentException.class,()->new BslMethodBatchJobs(registry).read(Map.of("projectName","P","items",List.of()),r->null,0));assertEquals(0,registry.size());}finally{registry.shutdown();}}
 @Test public void contextQueueDoesNotOccupyOrdinaryWorkers()throws Exception {var registry=BackgroundJobRegistry.createForTest();CountDownLatch release=new CountDownLatch(1);try{for(int i=0;i<4;i++)registry.startJob("bsl_method_batch",()->{release.await();return "{}";});String ordinary=registry.startJob("ordinary_read",()->"{}");assertEquals("DONE",registry.awaitStatus(ordinary,2000).orElseThrow().getState().name());}finally{release.countDown();registry.shutdown();}}
 @Test public void linkageFailureBecomesTerminalFailed()throws Exception {var registry=BackgroundJobRegistry.createForTest();try{var error=assertThrows(IllegalStateException.class,()->new BslMethodBatchJobs(registry).read(args(),r->{throw new NoClassDefFoundError("fixture");},2000));assertTrue(error.getMessage().startsWith("Batch job failed:"));}finally{registry.shutdown();}}
}
